  ["room: Upper landing", room10],
  ["room: Study and nursery", room11],
  ["room: Back bedroom", room12],
  ["room: Bathroom", room13],
  ["room: Top room under the roof", room14],
], { palette: "palette.json" });

g.save(out);
console.log(`saved ${out}`);
